pub(crate) fn has_value(&self, slot_index: usize) -> bool {
    // The slot may belong to a subsequent block if the receiver has consumed
    // the final slot of this block but has not yet advanced its head. In that
    // case the offset would wrap around and could observe a stale ready bit
    // from this block, so report that no value is available here.
    if self.header.start_index != start_index(slot_index) {
        return false;
    }

    let offset = offset(slot_index);
    let ready_bits = self.header.ready_slots.load(Acquire);
    is_ready(ready_bits, offset)
}

